const url = String(params.url || params.input || '').trim();
if (!url) return { error: 'pass params.url' };
const TRACKERS = /^(utm_|mc_|hsa_|_hs|matomo_|piwik_|vero_|mkt_)/i;
// Conservative blocklist. Bare `ref` and `source` were dropped after a
// 2026-05-21 code-review caught they collide with legitimate API params
// (e.g. ?ref=main on raw.githubusercontent.com).
const NAMED = new Set(['fbclid','gclid','gclsrc','dclid','msclkid','yclid','wickedid','igshid','si','ref_src','ref_url','spm','share_source','share_medium','share_campaign','_ga','__hsfp','__hssc','__hstc']);
try {
  const u = new URL(url);
  const removed = [];
  for (const key of [...u.searchParams.keys()]) {
    if (NAMED.has(key.toLowerCase()) || TRACKERS.test(key)) {
      removed.push(key);
      u.searchParams.delete(key);
    }
  }
  return { input: url, cleaned: u.toString(), removed, removed_count: removed.length };
} catch (e) {
  return { error: 'invalid URL: ' + e.message, input: url };
}
